additionalExercises.referenceSolution:
#include <iostream>
#include <print>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

struct Tracked {
    static inline int copies = 0;
    static inline int moves = 0;
    std::string v;

    explicit Tracked(std::string value) : v(std::move(value)) {}
    Tracked(const Tracked &other) : v(other.v) {
        ++copies;
    }
    Tracked(Tracked &&other) noexcept : v(std::move(other.v)) {
        ++moves;
    }
    Tracked &operator=(const Tracked &other) {
        v = other.v;
        ++copies;
        return *this;
    }
    Tracked &operator=(Tracked &&other) noexcept {
        v = std::move(other.v);
        ++moves;
        return *this;
    }
};

void my_swap(Tracked &a, Tracked &b) {
    if (&a == &b) {
        return;
    }
    Tracked tmp = std::move(a);
    a = std::move(b);
    b = std::move(tmp);
}

void rotate3(Tracked &a, Tracked &b, Tracked &c) {
    Tracked tmp = std::move(a);
    a = std::move(b);
    b = std::move(c);
    c = std::move(tmp);
}

int main() {
    std::string line;
    std::getline(std::cin, line);
    std::istringstream in(line);
    std::vector<std::string> words;
    std::string w;
    while (in >> w) {
        words.push_back(w);
    }
    std::vector<Tracked> items;
    items.reserve(words.size());
    for (const std::string &word : words) {
        items.emplace_back(word);
    }
    Tracked::copies = 0;
    Tracked::moves = 0;

    std::string command;
    while (std::cin >> command) {
        if (command == "swap") {
            std::size_t i, j;
            std::cin >> i >> j;
            my_swap(items[i - 1], items[j - 1]);
        } else if (command == "rotate") {
            std::size_t i, j, k;
            std::cin >> i >> j >> k;
            rotate3(items[i - 1], items[j - 1], items[k - 1]);
        } else if (command == "reverse") {
            for (std::size_t l = 0, r = items.size(); l + 1 < r; ++l, --r) {
                my_swap(items[l], items[r - 1]);
            }
        } else if (command == "show") {
            std::string s;
            for (const Tracked &t : items) {
                s += (s.empty() ? "" : " ") + t.v;
            }
            std::println("{}", s);
        } else {
            std::println("копий {}, перемещений {}", Tracked::copies, Tracked::moves);
        }
    }
    return 0;
}

